               {isSidebarCollapsed ? 'M' : 'Monthly Performance'}
             </h3>
             <div className={`space-y-1 ${!isSidebarCollapsed ? `pl-4` : ''}`}>
                {months.map(m => (
                  <button
                    key={m}
                    onClick={() => handleSidebarClick('month', m)}
                    className={`w-full flex items-center ${isSidebarCollapsed ? 'justify-center' : 'justify-between'} px-4 py-3 rounded-2xl text-sm font-semibold transition-all text-left ${
