                </h1>
              </div>
              <p className={`${isDarkMode ? 'text-slate-500' : 'text-slate-400'} text-sm font-bold tracking-tight`}>
                Analyzing {selectedPeriodType === 'quarter' ? `Quarter ${selectedValue}` : `Month of ${selectedValue}`} metrics
              </p>
